    if (typeof status !== 'number') {
        metricObserver('failure');
        return;
    }

    if (status >= 500) {
        metricObserver('5xx');
    } else if (status >= 400) {
        metricObserver('4xx');
    } else {
        metricObserver('failure');
    }
}

